  "AttendanceManager/package.json": "{\n  \"name\": \"attendance-tracker\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"node scripts/dev.js\",\n    \"dev:client\": \"vite\",\n    \"dev:server\": \"node server.js\",\n    \"build\": \"vite build\",\n    \"lint\": \"eslint .\",\n    \"preview\": \"vite preview\",\n    \"split:data\": \"node scripts/splitAttendanceData.mjs\",\n    \"clean-orphans\": \"node scripts/cleanOrphanedUsers.js\",\n    \"deploy:rules\": \"node scripts/deploy_firestore_rules.mjs\"\n  },\n  \"dependencies\": {\n    \"firebase\": \"^12.9.0\",\n    \"firebase-admin\": \"^14.3.0\",\n    \"framer-motion\": \"^12.29.2\",\n    \"html2canvas\": \"^1.4.1\",\n    \"jspdf\": \"^4.2.1\",\n    \"lucide-react\": \"^1.29.0\",\n    \"react\": \"^19.2.0\",\n    \"react-dom\": \"^19.2.0\",\n    \"react-router-dom\": \"^7.13.0\",\n    \"recharts\": \"^3.7.0\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^9.39.1\",\n    \"@tailwindcss/postcss\": \"^4.1.18\",\n    \"@types/react\": \"^19.2.5\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^5.1.1\",\n    \"eslint\": \"^9.39.1\",\n    \"eslint-plugin-react-hooks\": \"^7.0.1\",\n    \"eslint-plugin-react-refresh\": \"^0.4.24\",\n    \"globals\": \"^16.5.0\",\n    \"vite\": \"^7.2.4\"\n  }\n}\n",
  "package.json": "{\n  \"name\": \"splitwise-ai-app\",\n  \"version\": \"1.0.0\",\n  \"description\": \"SplitWise AI - Intelligent Expense Sharing and Multimodal Receipt Splitting\",\n  \"main\": \"server.js\",\n  \"scripts\": {\n    \"start\": \"node server.js\",\n    \"dev\": \"node server.js\",\n    \"compile-java\": \"javac -d bin src/com/splitwise/*.java\",\n    \"run-java-demo\": \"java -cp bin com.splitwise.DebtSimplifier\"\n  },\n  \"keywords\": [\n    \"splitwise\",\n    \"ai\",\n    \"receipt-scanner\",\n    \"gemini\",\n    \"java\",\n    \"debt-simplification\"\n  ],\n  \"author\": \"\",\n  \"license\": \"ISC\",\n  \"dependencies\": {\n    \"cors\": \"^2.8.5\",\n    \"dotenv\": \"^16.4.7\",\n    \"express\": \"^4.21.2\"\n  }\n}\n",
  "attendancemanager/package.json": "{\n  \"name\": \"attendance-tracker\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"node scripts/dev.js\",\n    \"dev:client\": \"vite\",\n    \"dev:server\": \"node server.js\",\n    \"build\": \"vite build\",\n    \"lint\": \"eslint .\",\n    \"preview\": \"vite preview\",\n    \"split:data\": \"node scripts/splitAttendanceData.mjs\",\n    \"clean-orphans\": \"node scripts/cleanOrphanedUsers.js\",\n    \"deploy:rules\": \"node scripts/deploy_firestore_rules.mjs\"\n  },\n  \"dependencies\": {\n    \"firebase\": \"^12.9.0\",\n    \"firebase-admin\": \"^14.3.0\",\n    \"framer-motion\": \"^12.29.2\",\n    \"html2canvas\": \"^1.4.1\",\n    \"jspdf\": \"^4.2.1\",\n    \"lucide-react\": \"^1.29.0\",\n    \"react\": \"^19.2.0\",\n    \"react-dom\": \"^19.2.0\",\n    \"react-router-dom\": \"^7.13.0\",\n    \"recharts\": \"^3.7.0\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^9.39.1\",\n    \"@tailwindcss/postcss\": \"^4.1.18\",\n    \"@types/react\": \"^19.2.5\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^5.1.1\",\n    \"eslint\": \"^9.39.1\",\n    \"eslint-plugin-react-hooks\": \"^7.0.1\",\n    \"eslint-plugin-react-refresh\": \"^0.4.24\",\n    \"globals\": \"^16.5.0\",\n    \"vite\": \"^7.2.4\"\n  }\n}\n",
