  "attendancemanager/deploy_firestore_rules.mjs": "import { initializeApp, cert } from \"firebase-admin/app\";\nimport { getSecurityRules } from \"firebase-admin/security-rules\";\nimport * as fs from \"fs\";\n\nconst serviceAccount = JSON.parse(fs.readFileSync(\"./serviceAccountKey.json\", \"utf8\"));\nconst rulesSource = fs.readFileSync(\"./firestore.rules\", \"utf8\");\n\nconst app = initializeApp({\n  credential: cert(serviceAccount),\n  projectId: serviceAccount.project_id,\n});\n\nasync function deployRules() {\n  try {\n    console.log(\"Deploying firestore.rules to project:\", serviceAccount.project_id);\n    const rules = getSecurityRules(app);\n    const ruleset = await rules.releaseFirestoreRulesetFromSource(rulesSource);\n    console.log(\"Successfully released ruleset:\", ruleset.name);\n    console.log(\"Rules deployment complete!\");\n  } catch (err) {\n    console.error(\"Failed to deploy firestore rules:\", err);\n    process.exit(1);\n  }\n}\n\ndeployRules();\n",
  "AttendanceManager/scripts/dev.js": "/* global process */\nimport { spawn } from \"child_process\";\n\nconst isWindows = process.platform === \"win32\";\nconst npmCommand = isWindows ? \"npm.cmd\" : \"npm\";\n\nconst processes = [];\n\nfunction startProcess(label, args) {\n  const child = spawn(npmCommand, args, {\n    shell: true,\n    stdio: \"inherit\",\n    env: process.env,\n  });\n\n  child.on(\"exit\", (code) => {\n    if (code && code !== 0) {\n      console.error(`${label} exited with code ${code}`);\n    }\n  });\n\n  processes.push(child);\n}\n\nfunction shutdown() {\n  processes.forEach((child) => {\n    if (!child.killed) {\n      child.kill();\n    }\n  });\n  process.exit(0);\n}\n\nprocess.on(\"SIGINT\", shutdown);\nprocess.on(\"SIGTERM\", shutdown);\n\nstartProcess(\"server\", [\"run\", \"dev:server\"]);\nstartProcess(\"client\", [\"run\", \"dev:client\"]);",
  "scripts/dev.js": "/* global process */\nimport { spawn } from \"child_process\";\n\nconst isWindows = process.platform === \"win32\";\nconst npmCommand = isWindows ? \"npm.cmd\" : \"npm\";\n\nconst processes = [];\n\nfunction startProcess(label, args) {\n  const child = spawn(npmCommand, args, {\n    shell: true,\n    stdio: \"inherit\",\n    env: process.env,\n  });\n\n  child.on(\"exit\", (code) => {\n    if (code && code !== 0) {\n      console.error(`${label} exited with code ${code}`);\n    }\n  });\n\n  processes.push(child);\n}\n\nfunction shutdown() {\n  processes.forEach((child) => {\n    if (!child.killed) {\n      child.kill();\n    }\n  });\n  process.exit(0);\n}\n\nprocess.on(\"SIGINT\", shutdown);\nprocess.on(\"SIGTERM\", shutdown);\n\nstartProcess(\"server\", [\"run\", \"dev:server\"]);\nstartProcess(\"client\", [\"run\", \"dev:client\"]);",
