  "usenotificationpermission.js": "// src/hooks/useNotificationPermission.js\nimport { useState, useCallback, useRef } from \"react\";\n\nexport function useNotificationPermission() {\n  const supported = typeof window !== \"undefined\" && \"Notification\" in window;\n\n  const [permission, setPermission] = useState(() =>\n    supported ? Notification.permission : \"unsupported\"\n  );\n  const [showModal, setShowModal] = useState(false);\n\n  // Store the pending promise resolver in a ref (not window global)\n  const resolveRef = useRef(null);\n\n  /**\n   * Call this before scheduling a reminder.\n   * - If already granted  → resolves true immediately\n   * - If denied           → resolves false immediately\n   * - If default (unknown) → shows our custom modal first, THEN\n   *   triggers the browser prompt when user clicks \"Allow\"\n   */\n  const requestPermissionIfNeeded = useCallback(() => {\n    return new Promise((resolve) => {\n      if (!supported) {\n        resolve(false);\n        return;\n      }\n      if (Notification.permission === \"granted\") {\n        resolve(true);\n        return;\n      }\n      if (Notification.permission === \"denied\") {\n        // Can't re-ask; permission was previously denied\n        resolve(false);\n        return;\n      }\n      // permission === \"default\" → show our pretty modal\n      resolveRef.current = resolve;\n      setShowModal(true);\n    });\n  }, [supported]);\n\n  function onAllow() {\n    setShowModal(false);\n    // Now trigger the real browser permission prompt\n    Notification.requestPermission().then((result) => {\n      setPermission(result);\n      resolveRef.current?.(result === \"granted\");\n      resolveRef.current = null;\n    });\n  }\n\n  function onDismiss() {\n    setShowModal(false);\n    resolveRef.current?.(false);\n    resolveRef.current = null;\n  }\n\n  return { permission, showModal, requestPermissionIfNeeded, onAllow, onDismiss };\n}",
  "AttendanceManager/src/index.css": "@import \"tailwindcss\";\r\n\r\n@config \"../tailwind.config.js\";\r\n\r\n:root {\r\n  color-scheme: dark;\r\n}\r\n\r\nhtml, body {\r\n  -webkit-overflow-scrolling: touch;\r\n}\r\n\r\n/* Global Custom Dark Scrollbars across the website */\r\n* {\r\n  scrollbar-width: thin;\r\n  scrollbar-color: #3f3f46 #18181b;\r\n}\r\n\r\n::-webkit-scrollbar {\r\n  width: 8px;\r\n  height: 8px;\r\n}\r\n\r\n::-webkit-scrollbar-track {\r\n  background: #18181b;\r\n  border-radius: 8px;\r\n}\r\n\r\n::-webkit-scrollbar-thumb {\r\n  background: #3f3f46;\r\n  border-radius: 8px;\r\n  border: 2px solid #18181b;\r\n}\r\n\r\n::-webkit-scrollbar-thumb:hover {\r\n  background: #52525b;\r\n}\r\n\r\n::-webkit-scrollbar-corner {\r\n  background: #18181b;\r\n}\r\n\r\n/* Hide scrollbars completely while preserving functional scrolling */\r\n.no-scrollbar {\r\n  -ms-overflow-style: none !important;\r\n  scrollbar-width: none !important;\r\n}\r\n.no-scrollbar::-webkit-scrollbar {\r\n  display: none !important;\r\n  width: 0 !important;\r\n  height: 0 !important;\r\n}\r\n\r\n@keyframes statusPop {\r\n  0% {\r\n    opacity: 0;\r\n    transform: scale(0.9);\r\n  }\r\n  100% {\r\n    opacity: 1;\r\n    transform: scale(1);\r\n  }\r\n}\r\n\r\n/* Theme ripple animation */\r\n@keyframes themeRipple {\r\n  0% {\r\n    clip-path: circle(0% at 95% 5%);\r\n  }\r\n  100% {\r\n    clip-path: circle(150% at 95% 5%);\r\n  }\r\n}\r\n\r\n@keyframes fadeUp {\r\n  0% {\r\n    opacity: 0;\r\n    transform: translateY(12px);\r\n  }\r\n  100% {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n\r\n:root {\r\n  color-scheme: light dark;\r\n  --bg-black: #000000;\r\n  --bg-card: #09090d;\r\n  --border-dark: rgba(255, 255, 255, 0.08);\r\n  --border-hover: rgba(99, 102, 241, 0.35);\r\n}\r\n\r\nhtml {\r\n  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\r\n}\r\n\r\nhtml.dark,\r\nbody.dark,\r\n.dark body {\r\n  background-color: #000000;\r\n  color: #f4f4f5;\r\n  color-scheme: dark;\r\n}\r\n\r\nhtml:not(.dark),\r\nbody:not(.dark) {\r\n  background-color: #f8fafc;\r\n  color: #0f172a;\r\n  color-scheme: light;\r\n}\r\n\r\nbody {\r\n  -webkit-font-smoothing: antialiased;\r\n  -moz-osx-font-smoothing: grayscale;\r\n}\r\n\r\nbutton {\r\n  cursor: pointer;\r\n}\r\n\r\n/* 60-120 FPS High-Performance Responsive Classes */\r\n@layer utilities {\r\n  .bg-pure-black {\r\n    background-color: #000000;\r\n  }\r\n  \r\n  .card-responsive-dark {\r\n    background-color: #09090d;\r\n    border: 1px solid rgba(255, 255, 255, 0.08);\r\n    transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1),\r\n                border-color 0.2s cubic-bezier(0.16, 1, 0.3, 1),\r\n                box-shadow 0.2s cubic-bezier(0.16, 1, 0.3, 1);\r\n    will-change: transform;\r\n  }\r\n\r\n  .card-responsive-dark:hover {\r\n    transform: translateY(-3px) scale(1.008);\r\n    border-color: rgba(99, 102, 241, 0.35);\r\n    box-shadow: 0 16px 36px -10px rgba(0, 0, 0, 0.8), 0 0 25px -4px rgba(99, 102, 241, 0.18);\r\n  }\r\n}\r\n\r\n/* Premium Desktop Glassmorphism Surfaces */\r\n@layer utilities {\r\n  .glass-card-desktop {\r\n    background: rgba(255, 255, 255, 0.85);\r\n    border: 1px solid rgba(228, 228, 231, 0.8);\r\n    backdrop-filter: blur(16px);\r\n    -webkit-backdrop-filter: blur(16px);\r\n  }\r\n\r\n  .dark .glass-card-desktop {\r\n    background: rgba(18, 18, 23, 0.72);\r\n    border: 1px solid rgba(255, 255, 255, 0.08);\r\n    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);\r\n  }\r\n\r\n  .glass-card-desktop-hover {\r\n    transition: transform 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94),\r\n                box-shadow 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94),\r\n                border-color 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94);\r\n    will-change: transform, box-shadow;\r\n  }\r\n\r\n  .glass-card-desktop-hover:hover {\r\n    transform: translateY(-3px);\r\n    box-shadow: 0 16px 36px -10px rgba(0, 0, 0, 0.15);\r\n  }\r\n\r\n  .dark .glass-card-desktop-hover:hover {\r\n    border-color: rgba(255, 255, 255, 0.16);\r\n    box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.6), 0 0 25px -5px rgba(99, 102, 241, 0.12);\r\n  }\r\n}\r",
