  "LazyGestures/setup.bat": "@echo off\ntitle AI Gesture Control Setup Protection\ncd /d \"%~dp0\\..\"\n\nif exist \"venv\\Scripts\\python.exe\" (\n    echo ===================================================\n    echo  [INFO] AI ENVIRONMENT IS ALREADY INSTALLED & READY!\n    echo ===================================================\n    echo Your virtual environment and all packages (OpenCV,\n    echo MediaPipe, PyAutoGUI, etc.) are already installed.\n    echo.\n    echo You do NOT need to run setup again.\n    echo.\n    echo To use the app, run: \"AI Gesture Controller.bat\"\n    echo ===================================================\n    echo.\n    set /p REINSTALL=\"Do you want to FORCE reinstall anyway? (Y/N): \"\n    if /i not \"%REINSTALL%\"==\"Y\" (\n        echo Setup skipped. Exiting...\n        timeout /t 3 >nul\n        exit /b 0\n    )\n)\n\necho Starting fresh environment installation...\npy -3 -m venv venv || python -m venv venv\ncall venv\\Scripts\\activate.bat\npip install -r requirements.txt\necho Setup complete!\npause\n",
