  "LazyGestures/tray_app.py": "\"\"\"\nSystem Tray Manager Module (Simplified Single Auto-Mode)\nProvides a clean, minimal tray menu:\n- Status: Active (Listening) / Paused\n- Show / Hide Camera Preview\n- Exit\n\"\"\"\n\nimport threading\nfrom PIL import Image, ImageDraw\nimport pystray\n\n\ndef create_tray_icon_image(is_active=True):\n    width = 64\n    height = 64\n    image = Image.new(\"RGBA\", (width, height), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(image)\n\n    outer_color = (0, 200, 100, 255) if is_active else (150, 150, 150, 255)\n    draw.ellipse((4, 4, width - 4, height - 4), fill=(30, 30, 30, 240), outline=outer_color, width=4)\n\n    inner_color = (0, 230, 120, 255) if is_active else (220, 100, 0, 255)\n    draw.ellipse((18, 18, width - 18, height - 18), fill=inner_color)\n\n    return image\n\n\nclass TrayApp:\n    def __init__(self, engine, dispatcher, toggle_preview_cb, exit_cb):\n        self.engine = engine\n        self.dispatcher = dispatcher\n        self.toggle_preview_cb = toggle_preview_cb\n        self.exit_cb = exit_cb\n\n        self.preview_visible = True\n        self.icon = None\n\n    def _get_status_text(self, item):\n        return f\"Status: {'Active (Listening)' if self.engine.is_enabled else 'Paused (Muted)'}\"\n\n    def _toggle_status(self, icon, item):\n        self.engine.toggle_enabled()\n        self._update_icon()\n\n    def _toggle_preview(self, icon, item):\n        self.preview_visible = not self.preview_visible\n        self.toggle_preview_cb(self.preview_visible)\n\n    def _is_preview_checked(self, item):\n        return self.preview_visible\n\n    def _on_exit(self, icon, item):\n        self.exit_cb()\n        icon.stop()\n\n    def _update_icon(self):\n        if self.icon:\n            self.icon.icon = create_tray_icon_image(self.engine.is_enabled)\n\n    def run(self):\n        menu = pystray.Menu(\n            pystray.MenuItem(self._get_status_text, self._toggle_status),\n            pystray.Menu.SEPARATOR,\n            pystray.MenuItem(\"Show Camera Preview\", self._toggle_preview, checked=self._is_preview_checked),\n            pystray.Menu.SEPARATOR,\n            pystray.MenuItem(\"Exit\", self._on_exit)\n        )\n\n        self.icon = pystray.Icon(\n            \"AI Gesture Control\",\n            create_tray_icon_image(self.engine.is_enabled),\n            \"AI Hand Gesture Controller\",\n            menu\n        )\n        self.icon.run()\n",
  "tray_app.py": "\"\"\"\nSystem Tray Manager Module (Simplified Single Auto-Mode)\nProvides a clean, minimal tray menu:\n- Status: Active (Listening) / Paused\n- Show / Hide Camera Preview\n- Exit\n\"\"\"\n\nimport threading\nfrom PIL import Image, ImageDraw\nimport pystray\n\n\ndef create_tray_icon_image(is_active=True):\n    width = 64\n    height = 64\n    image = Image.new(\"RGBA\", (width, height), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(image)\n\n    outer_color = (0, 200, 100, 255) if is_active else (150, 150, 150, 255)\n    draw.ellipse((4, 4, width - 4, height - 4), fill=(30, 30, 30, 240), outline=outer_color, width=4)\n\n    inner_color = (0, 230, 120, 255) if is_active else (220, 100, 0, 255)\n    draw.ellipse((18, 18, width - 18, height - 18), fill=inner_color)\n\n    return image\n\n\nclass TrayApp:\n    def __init__(self, engine, dispatcher, toggle_preview_cb, exit_cb):\n        self.engine = engine\n        self.dispatcher = dispatcher\n        self.toggle_preview_cb = toggle_preview_cb\n        self.exit_cb = exit_cb\n\n        self.preview_visible = True\n        self.icon = None\n\n    def _get_status_text(self, item):\n        return f\"Status: {'Active (Listening)' if self.engine.is_enabled else 'Paused (Muted)'}\"\n\n    def _toggle_status(self, icon, item):\n        self.engine.toggle_enabled()\n        self._update_icon()\n\n    def _toggle_preview(self, icon, item):\n        self.preview_visible = not self.preview_visible\n        self.toggle_preview_cb(self.preview_visible)\n\n    def _is_preview_checked(self, item):\n        return self.preview_visible\n\n    def _on_exit(self, icon, item):\n        self.exit_cb()\n        icon.stop()\n\n    def _update_icon(self):\n        if self.icon:\n            self.icon.icon = create_tray_icon_image(self.engine.is_enabled)\n\n    def run(self):\n        menu = pystray.Menu(\n            pystray.MenuItem(self._get_status_text, self._toggle_status),\n            pystray.Menu.SEPARATOR,\n            pystray.MenuItem(\"Show Camera Preview\", self._toggle_preview, checked=self._is_preview_checked),\n            pystray.Menu.SEPARATOR,\n            pystray.MenuItem(\"Exit\", self._on_exit)\n        )\n\n        self.icon = pystray.Icon(\n            \"AI Gesture Control\",\n            create_tray_icon_image(self.engine.is_enabled),\n            \"AI Hand Gesture Controller\",\n            menu\n        )\n        self.icon.run()\n",
  "lazygestures/tray_app.py": "\"\"\"\nSystem Tray Manager Module (Simplified Single Auto-Mode)\nProvides a clean, minimal tray menu:\n- Status: Active (Listening) / Paused\n- Show / Hide Camera Preview\n- Exit\n\"\"\"\n\nimport threading\nfrom PIL import Image, ImageDraw\nimport pystray\n\n\ndef create_tray_icon_image(is_active=True):\n    width = 64\n    height = 64\n    image = Image.new(\"RGBA\", (width, height), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(image)\n\n    outer_color = (0, 200, 100, 255) if is_active else (150, 150, 150, 255)\n    draw.ellipse((4, 4, width - 4, height - 4), fill=(30, 30, 30, 240), outline=outer_color, width=4)\n\n    inner_color = (0, 230, 120, 255) if is_active else (220, 100, 0, 255)\n    draw.ellipse((18, 18, width - 18, height - 18), fill=inner_color)\n\n    return image\n\n\nclass TrayApp:\n    def __init__(self, engine, dispatcher, toggle_preview_cb, exit_cb):\n        self.engine = engine\n        self.dispatcher = dispatcher\n        self.toggle_preview_cb = toggle_preview_cb\n        self.exit_cb = exit_cb\n\n        self.preview_visible = True\n        self.icon = None\n\n    def _get_status_text(self, item):\n        return f\"Status: {'Active (Listening)' if self.engine.is_enabled else 'Paused (Muted)'}\"\n\n    def _toggle_status(self, icon, item):\n        self.engine.toggle_enabled()\n        self._update_icon()\n\n    def _toggle_preview(self, icon, item):\n        self.preview_visible = not self.preview_visible\n        self.toggle_preview_cb(self.preview_visible)\n\n    def _is_preview_checked(self, item):\n        return self.preview_visible\n\n    def _on_exit(self, icon, item):\n        self.exit_cb()\n        icon.stop()\n\n    def _update_icon(self):\n        if self.icon:\n            self.icon.icon = create_tray_icon_image(self.engine.is_enabled)\n\n    def run(self):\n        menu = pystray.Menu(\n            pystray.MenuItem(self._get_status_text, self._toggle_status),\n            pystray.Menu.SEPARATOR,\n            pystray.MenuItem(\"Show Camera Preview\", self._toggle_preview, checked=self._is_preview_checked),\n            pystray.Menu.SEPARATOR,\n            pystray.MenuItem(\"Exit\", self._on_exit)\n        )\n\n        self.icon = pystray.Icon(\n            \"AI Gesture Control\",\n            create_tray_icon_image(self.engine.is_enabled),\n            \"AI Hand Gesture Controller\",\n            menu\n        )\n        self.icon.run()\n",
