  "SplitwiseAI/public/manifest.json": "{\n  \"name\": \"SplitWise AI - Intelligent Expense Sharing\",\n  \"short_name\": \"SplitWise AI\",\n  \"description\": \"AI-powered multimodal receipt scanner and Java debt optimization engine.\",\n  \"start_url\": \"/\",\n  \"id\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait-primary\",\n  \"background_color\": \"#070a11\",\n  \"theme_color\": \"#0b0f19\",\n  \"categories\": [\"finance\", \"productivity\", \"utilities\"],\n  \"icons\": [\n    {\n      \"src\": \"/icons/icon-192.png\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any maskable\"\n    },\n    {\n      \"src\": \"/icons/icon-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any maskable\"\n    },\n    {\n      \"src\": \"/icons/icon.svg\",\n      \"sizes\": \"any\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any\"\n    }\n  ],\n  \"shortcuts\": [\n    {\n      \"name\": \"1-Click Demo\",\n      \"short_name\": \"Demo\",\n      \"description\": \"Explore the interactive receipt simulator\",\n      \"url\": \"/#hero-preview\",\n      \"icons\": [{ \"src\": \"/icons/icon-192.png\", \"sizes\": \"192x192\" }]\n    },\n    {\n      \"name\": \"Java Debt Engine\",\n      \"short_name\": \"Algorithm\",\n      \"description\": \"Explore the cash-flow settlement algorithm\",\n      \"url\": \"/#algorithm\",\n      \"icons\": [{ \"src\": \"/icons/icon-192.png\", \"sizes\": \"192x192\" }]\n    }\n  ]\n}\n",
